package ai.ultron.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.speech.*;import android.speech.tts.TextToSpeech;import java.util.*;
public class MainActivity extends Activity {
 TextView status; TextToSpeech tts; boolean ready=false;
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setGravity(Gravity.CENTER);root.setBackgroundColor(Color.BLACK); TextView title=new TextView(this);title.setText("U L T R O N");title.setTextColor(Color.RED);title.setTextSize(30);root.addView(title);View orb=new View(this){protected void onDraw(Canvas c){super.onDraw(c);float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(x,y)*.8f;Paint p=new Paint(3);p.setShader(new RadialGradient(x,y,r,new int[]{Color.WHITE,Color.RED,0xff350000,Color.BLACK},null,Shader.TileMode.CLAMP));c.drawCircle(x,y,r,p);}};root.addView(orb,new LinearLayout.LayoutParams(-1,0,1));status=new TextView(this);status.setText("Tap to speak");status.setTextColor(Color.WHITE);root.addView(status);Button mic=new Button(this);mic.setText("Speak to ULTRON");root.addView(mic);mic.setOnClickListener(v->{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);try{startActivityForResult(i,1);}catch(Exception e){status.setText("Speech recognition unavailable");}});setContentView(root);tts=new TextToSpeech(this,s->{ready=s==TextToSpeech.SUCCESS;});}
 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==1&&result==RESULT_OK&&data!=null){ArrayList<String> words=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(words!=null&&!words.isEmpty()){String q=words.get(0);String answer="AI connection is not configured yet.";if(q.toLowerCase(Locale.ROOT).contains("hello"))answer="Hello. Ultron online.";status.setText(q+"\n"+answer);if(ready)tts.speak(answer,TextToSpeech.QUEUE_FLUSH,null,"reply");}}}
 protected void onDestroy(){if(tts!=null)tts.shutdown();super.onDestroy();}
}